/**  FR-DATA-002: what deleting an artist takes away — for the confirmation. */
export type RemovalInfo = {
	tracks: number,
	/**  Bytes as f64 (u64 is not a JS number). */
	bytes: number | null,
};

/**  FR-PLAY-007 repeat mode over IPC. */
